import { redact } from "./redaction.js";
const LOG_LEVELS = {
    debug: 10,
    info: 20,
    warn: 30,
    error: 40,
    none: Infinity,
};
const MIN_LEVEL = LOG_LEVELS[String(process.env.LOG_LEVEL ?? "info").toLowerCase()] ?? LOG_LEVELS.info;
function safeJSON(value) {
    try {
        return JSON.stringify(value);
    }
    catch {
        return String(value);
    }
}
/** Emit one line as JSON when the level clears the configured threshold. */
function log(level, message, meta) {
    if (LOG_LEVELS[level] < MIN_LEVEL)
        return;
    const redacted = redact(meta ?? {});
    const output = safeJSON({
        ...redacted,
        level,
        message,
        timestamp: new Date().toISOString(),
    });
    switch (level) {
        case "error":
            console.error(output);
            break;
        case "warn":
            console.warn(output);
            break;
        case "debug":
            console.debug(output);
            break;
        default:
            console.log(output);
    }
}
export const logger = {
    debug(msg, meta) {
        log("debug", msg, meta);
    },
    info(msg, meta) {
        log("info", msg, meta);
    },
    warn(msg, meta) {
        log("warn", msg, meta);
    },
    error(msg, meta) {
        log("error", msg, meta);
    },
};
